<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\TruckService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('TRUCK_CREATE_OWN');$errors=[];$values=$_POST?:['registration_country'=>'TZ','result_code'=>'PASS','roadworthiness_status'=>'ROADWORTHY'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$id=TruckService::create($_POST,(int)Auth::user()['id']);header('Location: '.Url::to('carrier/trucks/view.php?id='.$id.'&created=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}catch(Throwable$e){@file_put_contents(BASE_PATH.'/storage/logs/phase6b.log','['.date('c').'] '.$e->getMessage().PHP_EOL,FILE_APPEND|LOCK_EX);$errors[]='Truck registration could not be saved. Check the local error log.';}}$pageTitle='Register Truck';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Register truck</h1><p>Submit truck, insurance, inspection, and roadworthiness references for Operations verification.</p></div><span class="badge">Phase 6B</span></div><div class="notice">File uploads are deferred to Phase 10. Approval does not make a truck available or eligible.</div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><?php require BASE_PATH.'/app/Views/trucks/form.php';?><div class="actions"><button class="button">Submit truck for verification</button><a class="button secondary" href="<?=h(Url::to('carrier/trucks/index.php'))?>">Cancel</a></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
